values
  ('52de053a-3f55-5092-8b31-41032e1f2bbb', null, (select id from public.skills where slug = 'read-g3-figurative-language'), null, 'hard',
   $q$Mr. Haddad says, "You two stuck with it, and it paid off." What does Mr. Haddad mean?$q$, $q$[{"text":"The friends gave up early, so the game did not work.","is_correct":false,"misconception_token":"opposite-meaning"},{"text":"The friends got glued to the tablet, and someone paid them.","is_correct":false,"misconception_token":"literal-reading"},{"text":"The friends bought the game, so it cost them money.","is_correct":false,"misconception_token":"wrong-meaning"},{"text":"The friends kept trying, and their hard work led to success.","is_correct":true}]$q$::jsonb, $q$The friends kept trying, and their hard work led to success.$q$, $q$The friends did not quit when the frog froze, and in the end the game worked, so "stuck with it" means kept trying and "paid off" means it brought a good result. No one is paid real money.$q$, 'draft', 'dac957a5-dff8-5d38-a8c1-2ba349dfc8be')
