-- Passage rg3-literary-structure-pov-p05
insert into public.passages (id, code, skill_id, sat_alignment, grade_band, title, body, status)
values ('cf3db6f3-4622-55f7-901a-2f4597ab4dd3', 'rg3-literary-structure-pov-p05', (select id from public.skills where slug = 'read-g3-literary-structure-pov'), null,
        '3-5', $q$In the Goal$q$, $q$My gloves are on. My knees feel weak.
The whistle blows. I cannot speak.
The goal behind me looks so wide.
I wish that I could run and hide.

The first half starts. A shot flies by.
It slips past me, low and not high.
The other team begins to cheer.
We are down one. The score is clear.

In the second half, I plant my feet.
I tell myself, "I won't be beat."
A striker charges down the field.
I dive. My gloves become a shield.

Then Lena scores. The game is tied.
The final whistle: one to one.
I walk off tall and full of pride.
A tie can feel like we have won.$q$, 'draft')
